const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(+n||0), dateFmt=d=>new Date(d).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'});
const ANANTA_LOGO_DATA='data:image/jpeg;base64,';
const escHtml=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function amountWords(v){let n=Math.round((+v||0)*100)/100,rupees=Math.floor(n),paise=Math.round((n-rupees)*100);const one=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'],tens=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];const two=x=>x<20?one[x]:tens[Math.floor(x/10)]+(x%10?' '+one[x%10]:'');const three=x=>(x>=100?one[Math.floor(x/100)]+' Hundred'+(x%100?' ':''):'')+two(x%100);const parts=[];const crore=Math.floor(rupees/10000000);rupees%=10000000;const lakh=Math.floor(rupees/100000);rupees%=100000;const thousand=Math.floor(rupees/1000);rupees%=1000;if(crore)parts.push(three(crore)+' Crore');if(lakh)parts.push(three(lakh)+' Lakh');if(thousand)parts.push(three(thousand)+' Thousand');if(rupees)parts.push(three(rupees));if(!parts.length)parts.push('Zero');return parts.join(' ')+' Rupees'+(paise?' and '+two(paise)+' Paise':'')+' Only'}
function stateCodeFrom(c={}){return String(c.stateCode||c.gst||'').match(/^\d{2}/)?.[0]||''}

let state={token:sessionStorage.getItem('ananta_token')||'',user:JSON.parse(sessionStorage.getItem('ananta_user')||'null'),products:[],clients:[],invoices:[],quotations:[],suppliers:[],purchases:[],movements:[],dashboard:{},expenses:[],payments:[],reports:{},users:[],audit:[],settings:{},current:'dashboard',billItems:[]};
function toast(msg,bad=false){let t=$('#toast');if(!t){t=document.createElement('div');t.id='toast';document.body.appendChild(t)}t.textContent=msg;t.className=bad?'toast bad':'toast';setTimeout(()=>t.textContent='',2600)}
async function api(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json',...(state.token?{Authorization:`Bearer ${state.token}`}:{})};const r=await fetch(url,opt),d=await r.json().catch(()=>({}));if(!r.ok){if(r.status===401)logout();throw Error(d.error||'Request failed')}return d}
function f(l,n,v='',type='text'){return `<div class="field"><label for="${n}">${l}</label><input class="input" id="${n}" name="${n}" type="${type}" value="${v??''}"></div>`}
function modal(html,w='900px'){const x=document.createElement('div');x.id='modalWrap';x.className='modal-wrap';x.innerHTML=`<div class="modal" style="width:min(${w},100%)">${html}</div>`;document.body.appendChild(x);x.onclick=e=>{if(e.target===x)closeModal()}}
function closeModal(){$('#modalWrap')?.remove()}
function loginView(){document.body.innerHTML=`<div id="app"><div class="login-shell aurora-login"><section class="login-art"><div class="orb orb-a"></div><div class="orb orb-b"></div><div class="brand-stage"><div class="brand-frame"><img src="/assets/ananta-logo.jpg" class="brand"></div><div class="brand-copy"><span class="brand-chip">ANANTA BUSINESS OS</span><h1>Precision in every <em>operation.</em></h1><p>GST billing, inventory, purchases and finance in one secure Windows workspace.</p></div></div><div class="login-features"><span>✦ GST Ready</span><span>✦ Role Protected</span><span>✦ Local First</span></div></section><section class="login-panel"><form class="login-card" id="loginForm"><div class="login-mark">AI</div><div class="eyebrow">Secure workspace</div><h2>Welcome back</h2><p class="sub">Sign in to continue to Ananta Industries Business System.</p>${f('Username','username','admin')}${f('Password','password','','password')}<button class="btn btn-primary full">Enter workspace <span>→</span></button><div class="demo-box"><b>Admin:</b> admin / admin123 &nbsp; · &nbsp; <b>Biller:</b> biller / bill123<br><span>Change default passwords after first login.</span></div></form></section></div></div>`;$('#loginForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.token=d.token;state.user=d.user;sessionStorage.setItem('ananta_token',d.token);sessionStorage.setItem('ananta_user',JSON.stringify(d.user));boot()}catch(x){toast(x.message,true)}}}
function logout(){sessionStorage.clear();state.token='';state.user=null;loginView()}
const icon=k=>({dashboard:'▦',billing:'▤',quotations:'◇',invoices:'⌁',stock:'◫',purchases:'⇩',suppliers:'♧',clients:'♙',expenses:'₹',payments:'◉',reports:'▥',users:'♟',security:'⌾',settings:'⚙'}[k]||'•');
const navLabel=k=>({billing:'Bills',stock:'Inventory',dashboard:'Dashboard',quotations:'Quotations',invoices:'Invoices',purchases:'Purchases',suppliers:'Suppliers',clients:'Clients',expenses:'Expenses',payments:'Payments',reports:'Reports',users:'Users',security:'Security',settings:'Settings'}[k]||k);
function shell(){const a=state.user.role==='admin',nav=a?['dashboard','billing','quotations','invoices','stock','purchases','suppliers','clients','expenses','payments','reports','users','security','settings']:['billing','stock'];$('#app').innerHTML=`<div class="app-shell nova-shell"><aside class="sidebar" id="sidebar"><div class="side-brand"><div class="logo-shell"><img src="/assets/ananta-logo.jpg"></div><div><b>Ananta Industries</b><span>Business System</span></div></div><div class="nav-caption">Workspace</div><nav class="nav">${nav.map(x=>`<button data-view="${x}"><span class="ico">${icon(x)}</span><span>${navLabel(x)}</span><i>›</i></button>`).join('')}</nav><div class="side-bottom"><div class="security-pulse"><span></span> Secure local session</div><div class="user-chip"><div class="avatar">${state.user.name[0]}</div><div class="user-meta"><b>${state.user.name}</b><div class="mini">${a?'Administrator':'Billing Operator'}</div></div></div><button class="btn btn-ghost full" id="logout">Sign out</button></div></aside><main class="main"><header class="topbar"><div class="top-title"><button class="btn btn-secondary mobile-menu" id="menu">☰</button><div><span class="top-kicker">ANANTA INDUSTRIES</span><h1 id="pageTitle">${a?'Dashboard':'Bills'}</h1></div></div><div class="top-actions"><div class="live-dot"><span></span> Protected</div><span class="role-badge">${state.user.role}</span></div></header><div id="content" class="content"></div></main></div>`;$$('.nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('#logout').onclick=logout;$('#menu').onclick=()=>$('#sidebar').classList.toggle('open')}
async function loadAll(){state.products=await api('/api/products');state.clients=await api('/api/clients');state.invoices=await api('/api/invoices');if(state.user.role==='admin'){state.dashboard=await api('/api/dashboard');state.quotations=await api('/api/quotations');state.movements=await api('/api/stock-movements');state.suppliers=await api('/api/suppliers');state.purchases=await api('/api/purchases');state.expenses=await api('/api/expenses');state.payments=await api('/api/payments');state.reports=await api('/api/reports/summary');state.users=await api('/api/users');state.audit=await api('/api/audit');state.settings=await api('/api/settings')}else{state.dashboard={};state.quotations=[];state.movements=[];state.suppliers=[];state.purchases=[];state.expenses=[];state.payments=[];state.reports={};state.users=[];state.audit=[];state.settings={}}}
async function boot(){if(!state.token||!state.user)return loginView();try{await api('/api/me');shell();await loadAll();navigate(state.user.role==='admin'?'dashboard':'billing')}catch{logout()}}
function navigate(v){const a=state.user?.role==='admin',allowed=a?new Set(['dashboard','billing','quotations','invoices','stock','purchases','suppliers','clients','expenses','payments','reports','users','security','settings']):new Set(['billing','stock']);if(!allowed.has(v))v=a?'dashboard':'billing';state.current=v;$$('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#sidebar')?.classList.remove('open');$('#pageTitle').textContent=navLabel(v);({dashboard:renderDashboard,billing:renderBilling,quotations:renderQuotations,invoices:renderInvoices,stock:renderStock,purchases:renderPurchases,suppliers:renderSuppliers,clients:renderClients,expenses:renderExpenses,payments:renderPayments,reports:renderReports,users:renderUsers,security:renderSecurity,settings:renderSettings}[v]||renderDashboard)()}
function renderDashboard(){const d=state.dashboard;$('#content').innerHTML=`<div class="view dashboard-view"><div class="welcome-band"><div><div class="eyebrow">Business command center</div><h2>Good to see you, ${escHtml(state.user.name.split(' ')[0])}.</h2><p>Live view of billing, receivables, inventory and profitability.</p></div><button class="btn btn-primary btn-glow" onclick="navigate('billing')">＋ Create GST Invoice</button></div><div class="grid stats premium-stats">${[['Sales',money(d.totalSales),'↗'],['Outstanding',money(d.outstanding),'◔'],['Invoices',d.invoices,'▤'],['Low Stock',d.lowStock,'!'],['Gross Profit',money(d.profit),'◇'],['Expenses',money(d.expenses),'↓'],['Net Profit',money(d.netProfit),'✦']].map((x,i)=>`<div class="card stat stat-${i}"><div class="stat-top"><span class="stat-icon">${x[2]}</span><span class="trend-chip">LIVE</span></div><div class="lbl">${x[0]}</div><div class="num">${x[1]}</div><div class="stat-bar"><i></i></div></div>`).join('')}</div><div class="grid two dashboard-panels" style="margin-top:18px"><div class="card table-card elevated"><div class="panel-title"><div><span class="eyebrow">Activity</span><b>Recent invoices</b></div><button class="text-action" onclick="navigate('invoices')">View all →</button></div>${invoiceTable((d.recent||[]),false)}</div><div class="card action-hub elevated"><div class="eyebrow">Quick actions</div><h3>Run operations</h3><p class="sub">Jump directly into your most used workflows.</p><div class="action-grid">${['billing','quotations','stock','purchases','clients','expenses','reports'].map(x=>`<button class="action-tile" onclick="navigate('${x}')"><span>${icon(x)}</span><b>${navLabel(x)}</b><small>Open module</small></button>`).join('')}</div></div></div></div>`}
function badge(x){const cls=x==='Paid'||x==='Active'||x==='Converted'?'ok':x==='Partial'?'warn':x==='Cancelled'?'bad':'low';return `<span class="status ${cls}">${x}</span>`}
function invoiceTable(rows=state.invoices,actions=true){return `<div class="table-wrap"><table class="table"><thead><tr><th>Invoice</th><th>Client</th><th>Date</th><th>Total</th><th>Payment</th><th>Status</th>${actions?'<th></th>':''}</tr></thead><tbody>${rows.length?rows.map(i=>`<tr><td><b>${i.number}</b></td><td>${i.clientName}</td><td>${dateFmt(i.date)}</td><td class="money">${money(i.total)}</td><td>${badge(i.paymentStatus||'Unpaid')}</td><td>${badge(i.status||'Active')}</td>${actions?`<td><button class="btn btn-secondary" onclick="viewInvoice('${i.id}')">Open</button></td>`:''}</tr>`).join(''):`<tr><td colspan="7" class="empty">No invoices yet.</td></tr>`}</tbody></table></div>`}
function renderInvoices(){$('#content').innerHTML=`<div class="view"><div class="section-head"><div><div class="eyebrow">Sales documents</div><h2>Invoices</h2><p>GST invoices, payments, cancellation and credit notes.</p></div><button class="btn btn-primary" onclick="navigate('billing')">+ New Invoice</button></div><div class="card table-card">${invoiceTable()}</div></div>`}
function productPrice(p){return +(p.sellingPrice??p.price)||0}
function lineEditor(items,idp='lines'){return `<div id="${idp}">${items.map((r,i)=>{const p=state.products.find(x=>x.id===r.productId)||state.products[0]||{};return `<div class="line-item"><div class="field" style="margin:0"><label>Product</label><select class="select" onchange="lineChange(${i},'productId',this.value)">${state.products.map(x=>`<option value="${x.id}" ${x.id===r.productId?'selected':''}>${x.name} · Stock ${x.stock}</option>`).join('')}</select></div><div class="field" style="margin:0"><label>Qty</label><input class="input" type="number" min="1" value="${r.qty}" onchange="lineChange(${i},'qty',this.value)"></div><div><div class="mini">HSN ${p.hsn||'—'}</div><b>${money(productPrice(p))}</b><div class="mini">GST ${p.gst||0}%</div></div><button class="btn btn-danger" onclick="removeLine(${i})">×</button></div>`}).join('')}</div>`}
function renderBilling(){if(!state.products.length){$('#content').innerHTML=`<div class="view"><div class="card empty">No products available. Admin must add a product before billing.</div></div>`;return}const previousClient=$('#billClient')?.value||state.billClientId||'';if(!state.billItems.length)state.billItems=[{productId:state.products[0]?.id||'',qty:1}];$('#content').innerHTML=`<div class="view"><div class="section-head"><div><div class="eyebrow">GST Billing</div><h2>Create Invoice</h2><p>${state.user.role==='biller'?'Client master privacy is protected; the final GST invoice shows only legally required billing particulars.':'Gujarat clients use CGST + SGST; other states use IGST.'}</p></div></div><div class="invoice-builder"><div class="card"><div class="field"><label>Client</label><select id="billClient" class="select"><option value="">Select client...</option>${state.clients.map(c=>`<option value="${c.id}" ${c.id===previousClient?'selected':''}>${c.name}</option>`).join('')}</select></div>${state.user.role==='biller'?'<div class="note">Client contact, GST and address are protected from this account.</div>':''}${lineEditor(state.billItems)}<button class="btn btn-secondary" id="addLine">+ Add Product</button></div><div class="card summary-box"><div class="eyebrow">Invoice Summary</div><div id="billSummary"></div>${f('Discount ₹','discount','0','number')}<div class="field"><label>Reverse Charge</label><select id="reverseCharge" class="select"><option value="No">No</option><option value="Yes">Yes</option></select></div><div class="field"><label>Notes</label><textarea id="billNotes" class="textarea"></textarea></div><button class="btn btn-primary full" id="saveInvoice">Generate GST Invoice</button></div></div>${state.user.role==='biller'?`<div class="section-head" style="margin-top:28px"><div><div class="eyebrow">Bill history</div><h2>Recent Bills</h2></div></div><div class="card table-card">${invoiceTable(state.invoices.slice(0,15))}</div>`:''}</div>`;$('#billClient').onchange=e=>state.billClientId=e.target.value;$('#addLine').onclick=()=>{state.billClientId=$('#billClient')?.value||'';state.billItems.push({productId:state.products[0]?.id||'',qty:1});renderBilling()};const discountInput=$('#discount');if(discountInput)discountInput.oninput=renderBillSummary;const saveBtn=$('#saveInvoice');if(saveBtn)saveBtn.onclick=saveInvoice;renderBillSummary()}
function lineChange(i,k,v){const client=$('#billClient')?.value||'',disc=$('#discount')?.value||0,notes=$('#billNotes')?.value||'';state.billItems[i][k]=k==='qty'?+v:v;renderBilling();if($('#billClient'))$('#billClient').value=client;if($('#discount'))$('#discount').value=disc;if($('#billNotes'))$('#billNotes').value=notes;renderBillSummary()} function removeLine(i){const client=$('#billClient')?.value||'',disc=$('#discount')?.value||0,notes=$('#billNotes')?.value||'';state.billItems.splice(i,1);if(!state.billItems.length)state.billItems=[{productId:state.products[0]?.id||'',qty:1}];renderBilling();if($('#billClient'))$('#billClient').value=client;if($('#discount'))$('#discount').value=disc;if($('#billNotes'))$('#billNotes').value=notes;renderBillSummary()}
function totals(){let sub=0,tax=0;state.billItems.forEach(r=>{const p=state.products.find(x=>x.id===r.productId);if(p){const b=productPrice(p)*(+r.qty||0);sub+=b;tax+=b*(+p.gst||0)/100}});const disc=+($('#discount')?.value||0),ratio=sub?Math.max(0,sub-disc)/sub:0;return{sub,disc,tax:tax*ratio,total:Math.max(0,sub-disc)+tax*ratio}}
function renderBillSummary(){const e=$('#billSummary');if(!e)return;const t=totals();e.innerHTML=`<div class="summary-row"><span>Subtotal</span><b>${money(t.sub)}</b></div><div class="summary-row"><span>Estimated GST</span><b>${money(t.tax)}</b></div><div class="summary-row"><span>Discount</span><b>− ${money(t.disc)}</b></div><div class="summary-row total"><span>Total</span><span>${money(t.total)}</span></div>`}
async function saveInvoice(){const btn=$('#saveInvoice');try{const clientId=$('#billClient')?.value;if(!clientId)throw Error('Select a client');if(!state.billItems.length)throw Error('Add at least one product');if(btn){btn.disabled=true;btn.textContent='Generating…'}const i=await api('/api/invoices',{method:'POST',body:JSON.stringify({clientId,items:state.billItems.map(x=>({productId:x.productId,qty:+x.qty||1})),discount:+($('#discount')?.value||0),reverseCharge:$('#reverseCharge')?.value||'No',notes:$('#billNotes')?.value||''})});state.billItems=[];state.billClientId='';await loadAll();toast('GST Invoice generated successfully');await viewInvoice(i.id)}catch(e){toast(e.message||'Invoice generation failed',true)}finally{if(btn&&document.body.contains(btn)){btn.disabled=false;btn.textContent='Generate GST Invoice'}}}
function renderQuotations(){$('#content').innerHTML=`<div class="view"><div class="section-head"><div><div class="eyebrow">Estimate workflow</div><h2>Quotations</h2><p>Create estimate and convert to invoice in one click.</p></div><button class="btn btn-primary" onclick="quotationModal()">+ New Quotation</button></div><div class="card table-card"><div class="table-wrap"><table class="table"><thead><tr><th>No.</th><th>Client</th><th>Date</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${state.quotations.length?state.quotations.map(q=>`<tr><td><b>${q.number}</b></td><td>${q.clientName}</td><td>${dateFmt(q.date)}</td><td>${money(q.total)}</td><td>${badge(q.status)}</td><td>${q.status!=='Converted'?`<button class="btn btn-primary" onclick="convertQuotation('${q.id}')">Convert → Invoice</button>`:`<span class="mini">Converted</span>`}</td></tr>`).join(''):`<tr><td colspan="6" class="empty">No quotations.</td></tr>`}</tbody></table></div></div></div>`}
function quotationModal(){state.billItems=[{productId:state.products[0]?.id||'',qty:1}];modal(`<div class="modal-head"><h3>New Quotation</h3><button class="close" onclick="closeModal()">×</button></div><form id="quoteForm"><div class="field"><label>Client</label><select name="clientId" class="select" required>${state.clients.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select></div><div class="field"><label>Valid Until</label><input type="date" name="validUntil" class="input"></div><div id="qLines"></div><button type="button" class="btn btn-secondary" id="qAdd">+ Add Product</button>${f('Discount ₹','discount','0','number')}<div class="field"><label>Reverse Charge</label><select id="reverseCharge" class="select"><option value="No">No</option><option value="Yes">Yes</option></select></div><div class="field"><label>Notes</label><textarea class="textarea" name="notes"></textarea></div><button class="btn btn-primary">Save Quotation</button></form>`);renderQLines();$('#qAdd').onclick=()=>{state.billItems.push({productId:state.products[0].id,qty:1});renderQLines()};$('#quoteForm').onsubmit=async e=>{e.preventDefault();try{const x=Object.fromEntries(new FormData(e.target));x.items=state.billItems;await api('/api/quotations',{method:'POST',body:JSON.stringify(x)});await loadAll();closeModal();renderQuotations();toast('Quotation saved')}catch(z){toast(z.message,true)}}}
function renderQLines(){const e=$('#qLines');if(!e)return;e.innerHTML=state.billItems.map((r,i)=>`<div class="line-item"><select class="select" onchange="qChange(${i},'productId',this.value)">${state.products.map(p=>`<option value="${p.id}" ${p.id===r.productId?'selected':''}>${p.name}</option>`).join('')}</select><input class="input" type="number" min="1" value="${r.qty}" onchange="qChange(${i},'qty',this.value)"><b>${money(productPrice(state.products.find(p=>p.id===r.productId)))}</b><button type="button" class="btn btn-danger" onclick="qRemove(${i})">×</button></div>`).join('')}
function qChange(i,k,v){state.billItems[i][k]=k==='qty'?+v:v;renderQLines()} function qRemove(i){state.billItems.splice(i,1);renderQLines()}
async function convertQuotation(id){if(!confirm('Convert this quotation to invoice? Stock will be deducted.'))return;try{const i=await api(`/api/quotations/${id}/convert`,{method:'POST',body:'{}'});await loadAll();renderQuotations();toast('Quotation converted');viewInvoice(i.id)}catch(e){toast(e.message,true)}}
function renderStock(){$('#content').innerHTML=`<div class="view"><div class="section-head"><div><div class="eyebrow">Inventory control</div><h2>Stock</h2><p>Product master + full Stock IN / OUT history.</p></div>${state.user.role==='admin'?'<button class="btn btn-primary" onclick="productModal()">+ Product</button>':''}</div><div class="card table-card"><div class="table-wrap"><table class="table"><thead><tr><th>SKU / HSN</th><th>Product</th><th>Stock</th><th>Sell Price</th>${state.user.role==='admin'?'<th>Purchase</th>':''}<th>GST</th><th></th></tr></thead><tbody>${state.products.map(p=>`<tr><td>${p.sku}<div class="mini">HSN ${p.hsn||'—'}</div></td><td><b>${p.name}</b><div class="mini">${p.category||''}</div></td><td>${p.stock} ${p.unit} ${+p.stock<=+p.lowStock?badge('Low'):''}</td><td>${money(productPrice(p))}</td>${state.user.role==='admin'?`<td>${money(p.purchasePrice)}</td>`:''}<td>${p.gst}%</td><td>${state.user.role==='admin'?`<button class="btn btn-secondary" onclick="productModal('${p.id}')">Edit</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>${state.user.role==='admin'?`<div class="section-head" style="margin-top:28px"><div><h2>Stock Movement</h2><p>Every purchase, sale, cancellation and adjustment.</p></div></div><div class="card table-card"><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Product</th><th>Type</th><th>Qty</th><th>Balance</th><th>Reference</th></tr></thead><tbody>${state.movements.length?state.movements.map(m=>`<tr><td>${dateFmt(m.date)}</td><td>${m.productName}</td><td>${m.type}</td><td class="money">${m.qty>0?'+':''}${m.qty}</td><td>${m.balance}</td><td>${m.reference}<div class="mini">${m.note||''}</div></td></tr>`).join(''):`<tr><td colspan="6" class="empty">No movement yet.</td></tr>`}</tbody></table></div></div>`:''}</div>`}
function productModal(pid){const p=state.products.find(x=>x.id===pid)||{};modal(`<div class="modal-head"><h3>${pid?'Edit':'Add'} Product</h3><button class="close" onclick="closeModal()">×</button></div><form id="productForm"><div class="modal-grid">${f('SKU','sku',p.sku)}${f('HSN Code','hsn',p.hsn)}${f('Product Name','name',p.name)}${f('Category','category',p.category)}${f('Unit','unit',p.unit||'pcs')}${f('GST %','gst',p.gst||18,'number')}${f('Purchase Price ₹','purchasePrice',p.purchasePrice||0,'number')}${f('Selling Price ₹','sellingPrice',productPrice(p),'number')}${f('Current Stock','stock',p.stock||0,'number')}${f('Low Stock Level','lowStock',p.lowStock||10,'number')}</div><button class="btn btn-primary">Save Product</button></form>`);$('#productForm').onsubmit=async e=>{e.preventDefault();try{await api(pid?`/api/products/${pid}`:'/api/products',{method:pid?'PUT':'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await loadAll();closeModal();renderStock();toast('Product saved')}catch(x){toast(x.message,true)}}}
function renderSuppliers(){$('#content').innerHTML=`<div class="view"><div class="section-head"><div><div class="eyebrow">Vendor master</div><h2>Suppliers</h2><p>Purchase vendors and contact details.</p></div><button class="btn btn-primary" onclick="supplierModal()">+ Supplier</button></div><div class="card table-card"><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Phone</th><th>GST</th><th>Address</th><th></th></tr></thead><tbody>${state.suppliers.length?state.suppliers.map(s=>`<tr><td><b>${s.name}</b></td><td>${s.phone||'—'}</td><td>${s.gst||'—'}</td><td>${s.address||'—'}</td><td><button class="btn btn-danger" onclick="deleteSupplier('${s.id}')">Delete</button></td></tr>`).join(''):`<tr><td colspan="5" class="empty">No suppliers.</td></tr>`}</tbody></table></div></div></div>`}
function supplierModal(){modal(`<div class="modal-head"><h3>Add Supplier</h3><button class="close" onclick="closeModal()">×</button></div><form id="supForm">${f('Supplier Name','name')}${f('Phone','phone')}${f('Email','email','', 'email')}${f('GSTIN','gst')}<div class="field"><label>Address</label><textarea class="textarea" name="address"></textarea></div><button class="btn btn-primary">Save Supplier</button></form>`);$('#supForm').onsubmit=async e=>{e.preventDefault();await api('/api/suppliers',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await loadAll();closeModal();renderSuppliers();toast('Supplier added')}}
async function deleteSupplier(id){if(!confirm('Delete supplier?'))return;await api(`/api/suppliers/${id}`,{method:'DELETE'});await loadAll();renderSuppliers()}
function renderPurchases(){$('#content').innerHTML=`<div class="view"><div class="section-head"><div><div class="eyebrow">Procurement</div><h2>Purchases</h2><p>Purchase entry automatically adds stock and updates latest purchase price.</p></div><button class="btn btn-primary" onclick="purchaseModal()">+ Purchase Entry</button></div><div class="card table-card"><div class="table-wrap"><table class="table"><thead><tr><th>No.</th><th>Supplier</th><th>Bill No.</th><th>Date</th><th>Total</th></tr></thead><tbody>${state.purchases.length?state.purchases.map(p=>`<tr><td><b>${p.number}</b></td><td>${p.supplierName}</td><td>${p.billNo||'—'}</td><td>${dateFmt(p.date)}</td><td>${money(p.total)}</td></tr>`).join(''):`<tr><td colspan="5" class="empty">No purchases.</td></tr>`}</tbody></table></div></div></div>`}
function purchaseModal(){if(!state.suppliers.length)return toast('Add a supplier first',true);let rows=[{productId:state.products[0]?.id,qty:1,rate:state.products[0]?.purchasePrice||0}];modal(`<div class="modal-head"><h3>Purchase Entry</h3><button class="close" onclick="closeModal()">×</button></div><form id="purchaseForm"><div class="field"><label>Supplier</label><select class="select" name="supplierId">${state.suppliers.map(s=>`<option value="${s.id}">${s.name}</option>`).join('')}</select></div>${f('Supplier Bill No.','billNo')}<div id="purLines"></div><button type="button" id="purAdd" class="btn btn-secondary">+ Item</button><div class="field"><label>Notes</label><textarea class="textarea" name="notes"></textarea></div><button class="btn btn-primary">Save Purchase & Add Stock</button></form>`);const draw=()=>{$('#purLines').innerHTML=rows.map((r,i)=>`<div class="line-item"><select class="select" onchange="window.purSet(${i},'productId',this.value)">${state.products.map(p=>`<option value="${p.id}" ${p.id===r.productId?'selected':''}>${p.name}</option>`).join('')}</select><input class="input" type="number" min="1" value="${r.qty}" onchange="window.purSet(${i},'qty',this.value)"><input class="input" type="number" min="0" value="${r.rate}" onchange="window.purSet(${i},'rate',this.value)"><span></span></div>`).join('')};window.purSet=(i,k,v)=>{rows[i][k]=k==='productId'?v:+v;draw()};draw();$('#purAdd').onclick=()=>{rows.push({productId:state.products[0].id,qty:1,rate:state.products[0].purchasePrice||0});draw()};$('#purchaseForm').onsubmit=async e=>{e.preventDefault();try{const x=Object.fromEntries(new FormData(e.target));x.items=rows;await api('/api/purchases',{method:'POST',body:JSON.stringify(x)});await loadAll();closeModal();renderPurchases();toast('Purchase saved; stock updated')}catch(z){toast(z.message,true)}}}
function renderClients(){$('#content').innerHTML=`<div class="view"><div class="section-head"><div><div class="eyebrow">CRM + Ledger</div><h2>Clients</h2><p>Full contact details and outstanding ledger are admin-only.</p></div><button class="btn btn-primary" onclick="clientModal()">+ Client</button></div><div class="card table-card"><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Phone</th><th>GST</th><th>State</th><th></th></tr></thead><tbody>${state.clients.map(c=>`<tr><td><b>${c.name}</b><div class="mini">${c.company||''}</div></td><td>${c.phone||'—'}</td><td>${c.gst||'—'}</td><td>${c.state||'Gujarat'}</td><td><button class="btn btn-secondary" onclick="clientLedger('${c.id}')">Ledger</button> <button class="btn btn-secondary" onclick="clientModal('${c.id}')">Edit</button></td></tr>`).join('')}</tbody></table></div></div></div>`}
function clientModal(cid){const c=state.clients.find(x=>x.id===cid)||{};modal(`<div class="modal-head"><h3>${cid?'Edit':'Add'} Client</h3><button class="close" onclick="closeModal()">×</button></div><form id="clientForm"><div class="modal-grid">${f('Client Name','name',c.name)}${f('Company','company',c.company)}${f('Phone','phone',c.phone)}${f('Email','email',c.email,'email')}${f('GSTIN','gst',c.gst)}${f('State','state',c.state||'Gujarat')}${f('State Code','stateCode',c.stateCode||stateCodeFrom(c)||'24')}${f('PIN Code','pincode',c.pincode||'')}</div><div class="field"><label>Billing Address</label><textarea class="textarea" name="address">${c.address||''}</textarea></div><div class="field"><label>Delivery Address (leave blank if same)</label><textarea class="textarea" name="deliveryAddress">${c.deliveryAddress||''}</textarea></div><button class="btn btn-primary">Save Client</button></form>`);$('#clientForm').onsubmit=async e=>{e.preventDefault();try{await api(cid?`/api/clients/${cid}`:'/api/clients',{method:cid?'PUT':'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await loadAll();closeModal();renderClients();toast('Client saved')}catch(x){toast(x.message,true)}}}
async function clientLedger(id){try{const l=await api(`/api/ledger/${id}`);modal(`<div class="modal-head"><h3>${l.client.name} Ledger</h3><button class="close" onclick="closeModal()">×</button></div><div class="grid stats" style="grid-template-columns:repeat(3,1fr)"><div class="card stat"><div class="lbl">Billed</div><div class="num">${money(l.billed)}</div></div><div class="card stat"><div class="lbl">Paid</div><div class="num">${money(l.paid)}</div></div><div class="card stat"><div class="lbl">Pending</div><div class="num kpi-red">${money(l.pending)}</div></div></div><h3 style="margin-top:25px">Invoices</h3>${invoiceTable(l.invoices,false)}`,'1100px')}catch(e){toast(e.message,true)}}
function invoiceDocument(i){
  const c=i.clientSnapshot||{},sup=i.supplierSnapshot||{},isIGST=Number(i.igst||0)>0,discRatio=(+i.subtotal||0)>0?Math.max(0,(+i.subtotal-(+i.discount||0))/(+i.subtotal)):1;
  const rows=(i.items||[]).map((r,n)=>{const taxable=(+r.base||(+r.rate||0)*(+r.qty||0))*discRatio,tax=taxable*(+r.gst||0)/100,lineTotal=taxable+tax;return `<tr><td>${n+1}</td><td><b>${escHtml(r.name)}</b><br><small>SKU ${escHtml(r.sku||'—')} · HSN ${escHtml(r.hsn||'—')}</small></td><td>${escHtml(r.qty)} ${escHtml(r.unit||'')}</td><td>${money(r.rate)}</td><td>${money(taxable)}</td><td>${escHtml(r.gst||0)}%</td><td>${money(tax)}</td><td><b>${money(lineTotal)}</b></td></tr>`}).join('');
  const tax=isIGST?`<div class="tax-chip igst"><span>IGST</span><b>${money(i.igst)}</b></div>`:`<div class="tax-chip"><span>CGST</span><b>${money(i.cgst)}</b></div><div class="tax-chip"><span>SGST</span><b>${money(i.sgst)}</b></div>`;
  return `<div class="invoice-paper color-invoice"><div class="inv-accent"></div><div class="copy-mark">ORIGINAL FOR RECIPIENT</div><div class="inv-head"><div class="invoice-logo-block"><img src="/assets/ananta-logo.jpg" class="invoice-logo"><div class="supplier-meta"><b>GSTIN:</b> ${escHtml(sup.companyGSTIN||'NOT CONFIGURED')}<br>${escHtml(sup.companyAddress||'')} ${sup.companyPincode?'- '+escHtml(sup.companyPincode):''}<br>${escHtml(sup.companyPhone||'')} ${sup.companyEmail?`· ${escHtml(sup.companyEmail)}`:''}</div></div><div class="inv-title-box"><div class="inv-kicker">GST TAX INVOICE</div><div class="inv-number">${escHtml(i.number)}</div><div class="inv-date">Date: ${dateFmt(i.date)}</div><div class="inv-mini"><b>Place of Supply:</b> ${escHtml(i.placeOfSupply||c.state||'—')} ${escHtml(i.placeOfSupplyCode||stateCodeFrom(c)||'')}<br><b>Reverse Charge:</b> ${escHtml(i.reverseCharge||'No')}</div></div></div><div class="inv-info-grid"><div class="inv-panel bill-panel"><div class="inv-label">BILL TO / RECIPIENT</div><h3>${escHtml(i.clientName)}</h3><div>${escHtml(c.address||'')}</div><div>${escHtml(c.company||'')}</div><div><b>GSTIN/UIN:</b> ${escHtml(c.gst||'—')}</div><div><b>State:</b> ${escHtml(c.state||'—')} &nbsp; <b>Code:</b> ${escHtml(c.stateCode||stateCodeFrom(c)||'—')}</div>${c.deliveryAddress?`<div><b>Delivery:</b> ${escHtml(c.deliveryAddress)}</div>`:''}</div><div class="inv-panel payment-panel"><div class="inv-label">PAYMENT STATUS</div><div class="pay-status ${String(i.paymentStatus||'').toLowerCase()}">${escHtml(i.paymentStatus||'Unpaid')}</div><div class="payment-line"><span>Taxable Value</span><b>${money(i.taxable)}</b></div><div class="payment-line"><span>Total GST</span><b>${money(i.tax)}</b></div><div class="payment-line"><span>Balance</span><b>${money(i.balance)}</b></div></div></div><table class="inv-table gst-detail-table"><thead><tr><th>#</th><th>Description / HSN</th><th>Qty</th><th>Rate</th><th>Taxable</th><th>GST Rate</th><th>Tax Amt</th><th>Total</th></tr></thead><tbody>${rows}</tbody></table><div class="inv-bottom"><div class="inv-notes"><div class="inv-label">AMOUNT IN WORDS</div><p><b>${amountWords(i.total)}</b></p><div class="inv-label" style="margin-top:16px">NOTES / TERMS</div><p>${escHtml(i.notes||sup.defaultTerms||'Goods once sold will be subject to agreed commercial terms.')}</p><div class="inv-trust">GST RULE 46 READY • HSN • TAX BREAKUP • PLACE OF SUPPLY</div></div><div class="totals-card"><div class="total-line"><span>Gross Value</span><b>${money(i.subtotal)}</b></div><div class="total-line"><span>Discount</span><b>− ${money(i.discount)}</b></div><div class="total-line"><span>Taxable Value</span><b>${money(i.taxable)}</b></div><div class="tax-row">${tax}</div><div class="grand-total"><span>INVOICE TOTAL</span><b>${money(i.total)}</b></div>${state.user?.role==='admin'?`<div class="admin-margin"><span>Admin Margin</span><b>${money(i.profit)}</b></div>`:''}</div></div><div class="gst-bank-sign"><div class="bank-box"><div class="inv-label">BANK DETAILS</div>${sup.bankName?`<div><b>${escHtml(sup.bankName)}</b></div><div>A/C: ${escHtml(sup.accountNo||'—')}</div><div>IFSC: ${escHtml(sup.ifsc||'—')}</div><div>UPI: ${escHtml(sup.upiId||'—')}</div>`:'<div>Configure bank details in Admin → Settings.</div>'}</div><div class="sign-box"><div>For ${escHtml(sup.companyName||'ANANTA INDUSTRIES')}</div><div class="sign-space"></div><div class="sign-line"></div><b>${escHtml(sup.authorizedSignatory||'Authorized Signatory')}</b></div></div><div class="inv-footer"><div><b>ANANTA INDUSTRIES</b><span> • WHERE INNOVATION MEETS INFINITY</span></div><div class="inv-footer-right">System-generated tax invoice<br>Signature / digital signature to be applied as applicable</div></div></div>`
}

async function viewInvoice(id){try{const i=await api(`/api/invoices/${id}`);modal(`<div class="modal-head no-print"><h3>${i.number}</h3><div><button class="btn btn-primary" onclick="printInvoice('${i.id}')">Print / Color PDF</button> <button class="btn btn-secondary" onclick="saveDesktopPDF('${i.id}')">Save Color PDF</button> <button class="btn btn-secondary" onclick="shareWhatsApp('${i.id}')">WhatsApp</button> <button class="close" onclick="closeModal()">×</button></div></div>${invoiceDocument(i)}<div class="no-print" style="display:flex;gap:10px;flex-wrap:wrap;margin-top:16px">${state.user.role==='admin'?`<button class="btn btn-primary" onclick="paymentModal('${i.id}',${i.balance})" ${i.balance<=0||i.status==='Cancelled'?'disabled':''}>+ Record Payment</button>`:''}${state.user.role==='admin'&&i.status!=='Cancelled'?`<button class="btn btn-danger" onclick="cancelInvoice('${i.id}')">Cancel Invoice</button><button class="btn btn-secondary" onclick="creditModal('${i.id}',${i.total})">Credit Note</button>`:''}</div>`,'1100px');const mw=$('#modalWrap');if(mw){mw.classList.add('invoice-modal-wrap');mw.querySelector('.modal')?.classList.add('invoice-modal-premium')}setTimeout(()=>mw?.classList.add('invoice-ready'),20)}catch(e){toast(e.message,true)}}

function standaloneInvoiceHTML(i){
  const c=i.clientSnapshot||{},sup=i.supplierSnapshot||{},esc=escHtml,amt=v=>`₹${Number(v||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})}`;
  const d=new Date(i.date),dt=isNaN(d)?esc(i.date):d.toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}),ratio=(+i.subtotal||0)>0?Math.max(0,(+i.subtotal-(+i.discount||0))/(+i.subtotal)):1;
  const rows=(i.items||[]).map((r,n)=>{const taxable=(+r.base||(+r.rate||0)*(+r.qty||0))*ratio,tax=taxable*(+r.gst||0)/100,total=taxable+tax;return `<tr><td>${n+1}</td><td><strong>${esc(r.name)}</strong><small>SKU ${esc(r.sku||'—')} · HSN ${esc(r.hsn||'—')}</small></td><td>${esc(r.qty)} ${esc(r.unit||'')}</td><td>${amt(r.rate)}</td><td>${amt(taxable)}</td><td>${esc(r.gst||0)}%</td><td>${amt(tax)}</td><td class="right"><strong>${amt(total)}</strong></td></tr>`}).join('');
  const taxRows=Number(i.igst||0)>0?`<div class="taxrow"><span>IGST</span><b>${amt(i.igst)}</b></div>`:`<div class="taxsplit"><div><span>CGST</span><b>${amt(i.cgst)}</b></div><div><span>SGST</span><b>${amt(i.sgst)}</b></div></div>`;
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(i.number)} - GST Tax Invoice</title><style>
  *{box-sizing:border-box;-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}html,body{margin:0;padding:0;background:#eaf3f8;color:#0e263a;font-family:Arial,"Segoe UI",sans-serif}body{padding:12px}.sheet{width:194mm;min-height:277mm;margin:0 auto;background:#fff;box-shadow:0 14px 40px #1233;position:relative;overflow:hidden}.accent{height:9px;background:linear-gradient(90deg,#0d4168,#36a8db,#0d4168)}.copy{text-align:center;font-size:8px;letter-spacing:1.6px;font-weight:900;color:#527085;padding-top:4px}.pad{padding-left:9mm;padding-right:9mm}.head{display:flex;justify-content:space-between;gap:16px;padding-top:5mm;padding-bottom:4mm}.logo{width:56mm;height:32mm;object-fit:contain;object-position:left center}.supplier{font-size:8.5px;line-height:1.45;color:#486172;max-width:90mm}.doc{text-align:right}.tag{display:inline-block;background:#0d4168;color:#fff;font-size:9px;font-weight:900;letter-spacing:1.2px;padding:7px 10px;border-radius:7px}.no{font-size:17px;font-weight:900;color:#187eaf;margin-top:8px}.meta{font-size:8.5px;line-height:1.5;color:#4e6676;margin-top:4px}.info{display:grid;grid-template-columns:1.25fr .75fr;gap:10px;padding-bottom:4mm}.panel{border:1px solid #cfe2ec;border-radius:10px;padding:10px 12px;background:#f9fdff}.client{border-left:5px solid #31a8db}.label{font-size:7.5px;color:#187eaf;font-weight:900;letter-spacing:1.3px;margin-bottom:5px}.client h2{font-size:15px;margin:0 0 5px;color:#0e263a}.client p{font-size:8.5px;line-height:1.4;color:#3f596a;margin:2px 0}.payment{background:#0e263a;color:#fff;border-color:#0e263a}.payment .label{color:#79d7ff}.payline{display:flex;justify-content:space-between;font-size:8.5px;margin-top:7px;color:#d8e9f2}.tablewrap{padding:0 9mm}.items{width:100%;border-collapse:separate;border-spacing:0;border:1px solid #cfe2ec;border-radius:9px;overflow:hidden}.items th{background:#167fac;color:#fff;text-align:left;font-size:7px;text-transform:uppercase;letter-spacing:.45px;padding:7px 6px}.items td{font-size:8px;padding:7px 6px;border-bottom:1px solid #e4eef3;vertical-align:top}.items tr:nth-child(even) td{background:#f2faff}.items tr:last-child td{border-bottom:0}.items small{display:block;color:#6b7e8a;font-size:6.8px;margin-top:2px}.right{text-align:right}.bottom{display:grid;grid-template-columns:1fr 66mm;gap:14px;padding-top:4mm;padding-bottom:3mm}.notes p{font-size:8.5px;color:#506775;line-height:1.45;margin:4px 0}.motto{font-size:7px;color:#6990a7;letter-spacing:1.1px;font-weight:800;margin-top:10px}.totals{border:1px solid #cfe2ec;border-radius:10px;overflow:hidden;background:#f7fbfd}.totalrow,.taxrow{display:flex;justify-content:space-between;padding:6px 8px;font-size:8.5px;border-bottom:1px solid #dceaf1}.taxrow{background:#e8f7ff;color:#0f668f}.taxsplit{display:grid;grid-template-columns:1fr 1fr;background:#e8f7ff;color:#0f668f;border-bottom:1px solid #dceaf1}.taxsplit>div{display:flex;justify-content:space-between;padding:6px 8px;font-size:8px}.taxsplit>div+div{border-left:1px solid #c5e4f2}.grand{display:flex;justify-content:space-between;align-items:center;background:#0e263a;color:#fff;padding:9px 8px}.grand span{font-size:8px;letter-spacing:.8px;font-weight:900}.grand b{font-size:15px;color:#71d5ff}.bankSign{display:grid;grid-template-columns:1fr 62mm;gap:14px;margin:0 9mm;padding:3mm 0;border-top:1px solid #cfe2ec}.bank,.sign{font-size:8px;line-height:1.45;color:#4d6574}.sign{text-align:center}.sigspace{height:13mm}.sigline{height:1px;background:#738c9a;margin:0 9mm 3px}.footer{margin:0 9mm;border-top:2px solid #31a8db;padding:2.5mm 0 4mm;display:flex;justify-content:space-between;align-items:end;font-size:7.5px;color:#648091}.footer img{width:32mm;height:14mm;object-fit:contain}.footright{text-align:right}.cancel{position:absolute;top:34mm;left:50%;transform:translateX(-50%) rotate(-12deg);border:4px solid #c62828;color:#c62828;font-size:28px;font-weight:900;padding:5px 12px;opacity:.16;display:${i.status==='Cancelled'?'block':'none'}}
  @page{size:A4;margin:0}@media print{html,body{background:#fff}body{padding:0}.sheet{width:210mm;min-height:297mm;margin:0;box-shadow:none}.pad{padding-left:10mm;padding-right:10mm}.tablewrap{padding:0 10mm}.bankSign,.footer{margin-left:10mm;margin-right:10mm}tr{page-break-inside:avoid}}
  </style></head><body><section class="sheet"><div class="accent"></div><div class="copy">ORIGINAL FOR RECIPIENT</div><div class="cancel">CANCELLED</div><div class="head pad"><div><img class="logo" src="${ANANTA_LOGO_DATA}"><div class="supplier"><b>GSTIN:</b> ${esc(sup.companyGSTIN||'NOT CONFIGURED')}<br>${esc(sup.companyAddress||'')} ${sup.companyPincode?'- '+esc(sup.companyPincode):''}<br>${esc(sup.companyPhone||'')} ${sup.companyEmail?' · '+esc(sup.companyEmail):''}</div></div><div class="doc"><div class="tag">GST TAX INVOICE</div><div class="no">${esc(i.number)}</div><div class="meta">Date: ${dt}<br><b>Place of Supply:</b> ${esc(i.placeOfSupply||c.state||'—')} ${esc(i.placeOfSupplyCode||stateCodeFrom(c)||'')}<br><b>Reverse Charge:</b> ${esc(i.reverseCharge||'No')}</div></div></div><div class="info pad"><div class="panel client"><div class="label">BILL TO / RECIPIENT</div><h2>${esc(i.clientName)}</h2><p>${esc(c.address||'')}</p><p>${esc(c.company||'')}</p><p><b>GSTIN/UIN:</b> ${esc(c.gst||'—')}</p><p><b>State:</b> ${esc(c.state||'—')} &nbsp; <b>Code:</b> ${esc(c.stateCode||stateCodeFrom(c)||'—')}</p>${c.deliveryAddress?`<p><b>Delivery:</b> ${esc(c.deliveryAddress)}</p>`:''}</div><div class="panel payment"><div class="label">TAX SUMMARY</div><div class="payline"><span>Taxable Value</span><b>${amt(i.taxable)}</b></div><div class="payline"><span>Total GST</span><b>${amt(i.tax)}</b></div><div class="payline"><span>Invoice Value</span><b>${amt(i.total)}</b></div><div class="payline"><span>Payment</span><b>${esc(i.paymentStatus||'Unpaid')}</b></div></div></div><div class="tablewrap"><table class="items"><thead><tr><th>#</th><th>Description / HSN</th><th>Qty</th><th>Rate</th><th>Taxable</th><th>GST</th><th>Tax Amt</th><th class="right">Total</th></tr></thead><tbody>${rows||'<tr><td colspan="8">No items found</td></tr>'}</tbody></table></div><div class="bottom pad"><div class="notes"><div class="label">AMOUNT IN WORDS</div><p><b>${esc(amountWords(i.total))}</b></p><div class="label" style="margin-top:10px">NOTES / TERMS</div><p>${esc(i.notes||sup.defaultTerms||'Goods once sold will be subject to agreed commercial terms.')}</p><div class="motto">GST RULE 46 READY • HSN • TAX BREAKUP • PLACE OF SUPPLY</div></div><div class="totals"><div class="totalrow"><span>Gross Value</span><b>${amt(i.subtotal)}</b></div><div class="totalrow"><span>Discount</span><b>− ${amt(i.discount)}</b></div><div class="totalrow"><span>Taxable Value</span><b>${amt(i.taxable)}</b></div>${taxRows}<div class="grand"><span>INVOICE TOTAL</span><b>${amt(i.total)}</b></div></div></div><div class="bankSign"><div class="bank"><div class="label">BANK DETAILS</div>${sup.bankName?`<b>${esc(sup.bankName)}</b><br>A/C: ${esc(sup.accountNo||'—')}<br>IFSC: ${esc(sup.ifsc||'—')}<br>UPI: ${esc(sup.upiId||'—')}`:'Configure bank details in Admin → Settings.'}</div><div class="sign"><div>For ${esc(sup.companyName||'ANANTA INDUSTRIES')}</div><div class="sigspace"></div><div class="sigline"></div><b>${esc(sup.authorizedSignatory||'Authorized Signatory')}</b></div></div><div class="footer"><div><b>ANANTA INDUSTRIES</b> · WHERE INNOVATION MEETS INFINITY</div><div class="footright">System-generated tax invoice<br>Signature / digital signature to be applied as applicable</div></div></section></body></html>`;
}

async function printInvoice(id){try{const i=await api(`/api/invoices/${id}`),w=window.open('','_blank','width=1000,height=900');if(!w)throw Error('Allow pop-ups for invoice printing');w.document.open();w.document.write(standaloneInvoiceHTML(i));w.document.close();w.onload=()=>setTimeout(()=>w.print(),300)}catch(e){toast(e.message,true)}}

async function saveDesktopPDF(id){try{const i=await api(`/api/invoices/${id}`);if(window.desktopAPI?.saveInvoicePDF){const r=await window.desktopAPI.saveInvoicePDF(`${String(i.number).replace(/[\\/]/g,'-')}.pdf`,standaloneInvoiceHTML(i));if(r?.ok)toast('Colour invoice PDF saved');else if(!r?.cancelled)throw Error(r?.error||'PDF save failed')}else{toast('Browser mode: opening clean invoice print view.');printInvoice(id)}}catch(e){toast(e.message,true)}}

function paymentModal(id,balance){modal(`<div class="modal-head"><h3>Record Payment</h3><button class="close" onclick="closeModal()">×</button></div><form id="payForm">${f('Amount ₹','amount',balance,'number')}<div class="field"><label>Mode</label><select class="select" name="mode"><option>Cash</option><option>UPI</option><option>Bank Transfer</option><option>Cheque</option></select></div>${f('Reference / UTR / Cheque No.','reference')}<button class="btn btn-primary">Save Payment</button></form>`);$('#payForm').onsubmit=async e=>{e.preventDefault();try{await api(`/api/invoices/${id}/payments`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await loadAll();closeModal();toast('Payment recorded');viewInvoice(id)}catch(x){toast(x.message,true)}}}
async function cancelInvoice(id){const reason=prompt('Cancellation reason:')||'';if(!confirm('Cancel invoice and restore stock?'))return;try{await api(`/api/invoices/${id}/cancel`,{method:'POST',body:JSON.stringify({reason})});await loadAll();closeModal();renderInvoices();toast('Invoice cancelled; stock restored')}catch(e){toast(e.message,true)}}
function creditModal(id,total){modal(`<div class="modal-head"><h3>Create Credit Note</h3><button class="close" onclick="closeModal()">×</button></div><form id="cnForm">${f('Credit Amount ₹','amount',total,'number')}${f('Reason','reason')}<button class="btn btn-primary">Create Credit Note</button></form>`);$('#cnForm').onsubmit=async e=>{e.preventDefault();try{await api(`/api/invoices/${id}/credit-note`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await loadAll();closeModal();toast('Credit note created');viewInvoice(id)}catch(x){toast(x.message,true)}}}
async function shareWhatsApp(id){const i=state.invoices.find(x=>x.id===id)||await api(`/api/invoices/${id}`),txt=`Ananta Industries Invoice ${i.number}%0AClient: ${i.clientName}%0ATotal: ${money(i.total)}%0APayment: ${i.paymentStatus}%0AThank you.`;window.open(`https://wa.me/?text=${encodeURIComponent(txt.replaceAll('%0A','\n'))}`,'_blank')}

function renderExpenses(){const rows=state.expenses||[];$('#content').innerHTML=`<div class="view"><div class="section-head"><div><div class="eyebrow">Finance control</div><h2>Expenses</h2><p>Track operating expenses separately from purchases.</p></div><button class="btn btn-primary" onclick="expenseModal()">+ Add Expense</button></div><div class="grid stats"><div class="card stat"><div class="lbl">Total Expenses</div><div class="num">${money(rows.reduce((a,b)=>a+(+b.amount||0),0))}</div></div></div><div class="card table-card" style="margin-top:18px"><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Category</th><th>Description</th><th>Mode</th><th>Amount</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dateFmt(x.date)}</td><td><b>${x.category}</b></td><td>${x.description||'—'}<div class="mini">${x.reference||''}</div></td><td>${x.mode}</td><td class="money">${money(x.amount)}</td><td><button class="btn btn-danger" onclick="deleteExpense('${x.id}')">Delete</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No expenses recorded.</td></tr>'}</tbody></table></div></div></div>`}
function expenseModal(){modal(`<div class="modal-head"><h3>Add Expense</h3><button class="close" onclick="closeModal()">×</button></div><form id="expenseForm"><div class="modal-grid">${f('Date','date',new Date().toISOString().slice(0,10),'date')}${f('Category','category','Office')}${f('Amount ₹','amount','','number')}<div class="field"><label>Payment Mode</label><select class="select" name="mode"><option>Cash</option><option>UPI</option><option>Bank Transfer</option><option>Cheque</option><option>Card</option></select></div></div>${f('Description','description')}${f('Reference','reference')}<button class="btn btn-primary">Save Expense</button></form>`);$('#expenseForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/expenses',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});await loadAll();closeModal();renderExpenses();toast('Expense saved')}catch(x){toast(x.message,true)}}}
async function deleteExpense(id){if(!confirm('Delete this expense?'))return;await api('/api/expenses/'+id,{method:'DELETE'});await loadAll();renderExpenses();toast('Expense deleted')}
function renderPayments(){const rows=state.payments||[];$('#content').innerHTML=`<div class="view"><div class="section-head"><div><div class="eyebrow">Receipts</div><h2>Payments</h2><p>All invoice payments and collection references.</p></div></div><div class="grid stats"><div class="card stat"><div class="lbl">Total Collected</div><div class="num">${money(rows.reduce((a,b)=>a+(+b.amount||0),0))}</div></div></div><div class="card table-card" style="margin-top:18px"><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Invoice</th><th>Client</th><th>Mode</th><th>Reference</th><th>Amount</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dateFmt(x.date)}</td><td><b>${x.invoiceNumber}</b></td><td>${x.clientName}</td><td>${x.mode}</td><td>${x.reference||'—'}</td><td class="money">${money(x.amount)}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No payments recorded.</td></tr>'}</tbody></table></div></div></div>`}
function renderReports(){const r=state.reports||{};$('#content').innerHTML=`<div class="view"><div class="section-head"><div><div class="eyebrow">Business intelligence</div><h2>Reports</h2><p>GST, sales, cost, purchases and profitability summary.</p></div></div><div class="grid stats">${[['Sales',r.sales],['Taxable Sales',r.taxable],['GST Collected',r.tax],['Collected',r.paid],['Outstanding',r.outstanding],['Purchase Cost',r.purchaseTotal],['COGS',r.cost],['Gross Profit',r.grossProfit],['Expenses',r.expenses],['Net Profit',r.netProfit]].map(x=>`<div class="card stat"><div class="lbl">${x[0]}</div><div class="num">${money(x[1])}</div></div>`).join('')}</div><div class="card table-card" style="margin-top:18px"><div style="padding:20px"><b>Low Stock Report</b></div><div class="table-wrap"><table class="table"><thead><tr><th>SKU</th><th>Product</th><th>Available</th><th>Alert At</th></tr></thead><tbody>${(r.lowStock||[]).map(p=>`<tr><td>${p.sku}</td><td><b>${p.name}</b></td><td>${p.stock} ${p.unit}</td><td>${p.lowStock} ${p.unit}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No low-stock products.</td></tr>'}</tbody></table></div></div></div>`}
function renderUsers(){const rows=state.users||[];$('#content').innerHTML=`<div class="view"><div class="section-head"><div><div class="eyebrow">Access control</div><h2>Users</h2><p>Create administrators or restricted billers. Biller access is limited to Bills and Inventory.</p></div><button class="btn btn-primary" onclick="userModal()">+ Add User</button></div><div class="card table-card"><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(u=>`<tr><td><b>${u.name}</b></td><td>${u.username}</td><td>${badge(u.role==='admin'?'Admin':'Biller')}</td><td>${badge(u.active===false?'Disabled':'Active')}</td><td><button class="btn btn-secondary" onclick="userModal('${u.id}')">Edit / Password</button></td></tr>`).join('')}</tbody></table></div></div></div>`}
function userModal(id){const u=(state.users||[]).find(x=>x.id===id)||{};modal(`<div class="modal-head"><h3>${id?'Edit':'Add'} User</h3><button class="close" onclick="closeModal()">×</button></div><form id="userForm">${f('Display Name','name',u.name||'')}${id?`<div class="field"><label>Username</label><input class="input" value="${u.username||''}" disabled></div>`:f('Username','username','')}${f(id?'New Password (leave blank to keep)':'Password','password','','password')}<div class="field"><label>Role</label><select class="select" name="role"><option value="biller" ${u.role==='biller'?'selected':''}>Biller — Bills + Inventory only</option><option value="admin" ${u.role==='admin'?'selected':''}>Administrator — Full access</option></select></div>${id?`<label class="check"><input type="checkbox" name="active" ${u.active!==false?'checked':''}> Account active</label>`:''}<button class="btn btn-primary">Save User</button></form>`);$('#userForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(id)d.active=e.target.active.checked;try{await api(id?'/api/users/'+id:'/api/users',{method:id?'PUT':'POST',body:JSON.stringify(d)});await loadAll();closeModal();renderUsers();toast('User saved')}catch(x){toast(x.message,true)}}}
function renderSecurity(){const rows=state.audit||[];$('#content').innerHTML=`<div class="view"><div class="section-head"><div><div class="eyebrow">Security center</div><h2>Audit & Protection</h2><p>Recent sign-ins and sensitive administrative actions.</p></div><button class="btn btn-secondary" onclick="downloadBackup()">Export Backup</button></div><div class="grid stats"><div class="card stat"><div class="lbl">Session Lifetime</div><div class="num">8h</div></div><div class="card stat"><div class="lbl">Login Lock</div><div class="num">5 attempts</div></div><div class="card stat"><div class="lbl">Biller Scope</div><div class="num">2 modules</div></div></div><div class="card" style="margin-top:18px"><div class="eyebrow">Protection enabled</div><p class="mini">Password hashing • expiring signed sessions • login throttling • server-side role checks • local-only random port • CSP/security headers • Electron navigation lock • permission denial • audit log.</p></div><div class="card table-card" style="margin-top:18px"><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>User</th><th>Role</th><th>Action</th><th>Detail</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dateFmt(x.date)}</td><td>${x.user}</td><td>${x.role}</td><td><b>${x.action}</b></td><td>${x.detail||'—'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No audit events yet.</td></tr>'}</tbody></table></div></div></div>`}
async function downloadBackup(){try{const r=await fetch('/api/backup',{headers:{Authorization:`Bearer ${state.token}`}});if(!r.ok)throw Error('Backup export failed');const blob=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`ananta-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);await loadAll();toast('Backup exported')}catch(e){toast(e.message,true)}}
function renderSettings(){const s=state.settings||{};$('#content').innerHTML=`<div class="view"><div class="section-head"><div><div class="eyebrow">GST & Business Identity</div><h2>Settings</h2><p>These details are printed on every GST tax invoice. Enter the exact details from the GST registration certificate.</p></div></div><form class="card" id="settingsForm" style="max-width:980px"><div class="settings-logo-preview"><img src="/assets/ananta-logo.jpg"><div><b>Official invoice branding</b><div class="mini">This supplied logo is used on login, sidebar and GST invoice/PDF.</div></div></div><div class="modal-grid">${f('Legal Company Name','companyName',s.companyName||'ANANTA INDUSTRIES')}${f('GSTIN (mandatory for GST invoice)','companyGSTIN',s.companyGSTIN||'')}${f('Company State','companyState',s.companyState||'Gujarat')}${f('State Code','companyStateCode',s.companyStateCode||'24')}${f('PIN Code','companyPincode',s.companyPincode||'')}${f('Phone','companyPhone',s.companyPhone||'')}${f('Email','companyEmail',s.companyEmail||'','email')}${f('Authorized Signatory','authorizedSignatory',s.authorizedSignatory||'')}${f('Invoice Prefix','invoicePrefix',s.invoicePrefix||'AI')}${f('Quotation Prefix','quotationPrefix',s.quotationPrefix||'QT')}${f('Bank Name','bankName',s.bankName||'')}${f('Account Number','accountNo',s.accountNo||'')}${f('IFSC','ifsc',s.ifsc||'')}${f('UPI ID','upiId',s.upiId||'')}</div><div class="field"><label>Registered Business Address</label><textarea class="textarea" name="companyAddress" required>${s.companyAddress||'GIDC Naroda, Ahmedabad, Gujarat'}</textarea></div><div class="field"><label>Default Invoice Terms</label><textarea class="textarea" name="defaultTerms">${s.defaultTerms||'Subject to Ahmedabad jurisdiction. Goods once sold are governed by agreed commercial terms.'}</textarea></div><div class="note"><b>GST compliance:</b> Supplier GSTIN, address and state details must be correct before generating a tax invoice. If e-invoicing/IRN is applicable to your turnover/category, registration on the GST Invoice Registration Portal is still required; this app does not invent an IRN or government QR code.</div><button class="btn btn-primary" style="margin-top:16px">Save GST Settings</button></form></div>`;$('#settingsForm').onsubmit=async e=>{e.preventDefault();try{state.settings=await api('/api/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});toast('GST settings saved')}catch(x){toast(x.message,true)}}}
Object.assign(window,{navigate,closeModal,viewInvoice,lineChange,removeLine,quotationModal,qChange,qRemove,convertQuotation,productModal,supplierModal,deleteSupplier,purchaseModal,clientModal,clientLedger,paymentModal,cancelInvoice,creditModal,shareWhatsApp,expenseModal,deleteExpense,userModal,downloadBackup,saveDesktopPDF,printInvoice});
boot();
